const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();function hit(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hits=ray.intersectObjects(room.children,true);if(!hits.length)return null;for(const h of hits){let o=h.object;while(o&&o!==room){if(o.userData.id)return o.userData.id;o=o.parent}if(h.object.material?.transparent&&h.object.material?.depthWrite===false)continue;return null;}return null}
let glowMeshes=[];function hoverGlow(id){for(let [m,orig,copy] of glowMeshes){m.material=orig;copy.dispose()}glowMeshes=[];if(id&&items[id]&&!renderer.isSoftware)items[id].g.traverse(m=>{if(m.isMesh&&m.material?.isMeshStandardMaterial){let orig=m.material,copy=orig.clone();copy.emissive=new THREE.Color(0x6e4c18);copy.emissiveIntensity=.13;m.material=copy;glowMeshes.push([m,orig,copy])}})}
let down=null,pinch=null;const fingers=new Map();
renderer.domElement.addEventListener('pointerdown',e=>{renderer.domElement.setPointerCapture(e.pointerId);fingers.set(e.pointerId,{x:e.clientX,y:e.clientY});down={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,t:performance.now(),moved:false};if(fingers.size===2){const ar=[...fingers.values()];pinch={distance:Math.hypot(ar[0].x-ar[1].x,ar[0].y-ar[1].y),zoom:camera.zoom};down.moved=true;}});
renderer.domElement.addEventListener('pointermove',e=>{if(!started||dialog.open)return;if(fingers.has(e.pointerId))fingers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(fingers.size===2&&pinch){const ar=[...fingers.values()];camera.zoom=THREE.MathUtils.clamp(pinch.zoom*Math.hypot(ar[0].x-ar[1].x,ar[0].y-ar[1].y)/pinch.distance,1,1.85);renderer.invalidate?.();return}if(down&&fingers.has(e.pointerId)){let dx=e.clientX-down.lastX,dy=e.clientY-down.lastY;if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)down.moved=true;if(down.moved)turnGaze(-dx*.003,dy*.0025);down.lastX=e.clientX;down.lastY=e.clientY;renderer.domElement.style.cursor='grabbing';return}if(e.pointerType==='touch')return;let id=hit(e);renderer.domElement.style.cursor=id?'pointer':'grab';if(hovered!==id){hovered=id;hoverGlow(id);}});
renderer.domElement.addEventListener('pointerup',e=>{const tap=down&&!down.moved&&fingers.size===1;fingers.delete(e.pointerId);pinch=null;if(tap){let id=hit(e);if(id)activate(id)}down=null;});
renderer.domElement.addEventListener('pointercancel',e=>{fingers.delete(e.pointerId);down=null;pinch=null});
renderer.domElement.addEventListener('wheel',e=>{if(!started||dialog.open)return;e.preventDefault();camera.zoom=THREE.MathUtils.clamp(camera.zoom-e.deltaY*.001,1,1.85);renderer.invalidate?.();},{passive:false});
$('#lookLeft').onclick=()=>{if(started&&!dialog.open)turnGaze(-.32,0)};$('#lookRight').onclick=()=>{if(started&&!dialog.open)turnGaze(.32,0)};
addEventListener('keydown',e=>{if(!started||dialog.open||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();turnGaze(e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0,e.key==='ArrowUp'?.08:e.key==='ArrowDown'?-.08:0)});

function help(){openModal(panel(`<p class="eyebrow">A ROOM FULL OF LITTLE SECRETS</p><h1>我在房间里放了好多东西！</h1><p>生日蛋糕、留声机、信封、百合、礼物盒、照相机和地球仪，都藏着为你准备的内容。</p><p>窗帘、窗户、台灯、气球、抽屉、小熊、时钟，也都可以点点试试~</p><p class="quiet">已发现 ${discovered.size} / ${total} 处。蜡烛和探索进度会保存在这个浏览器。<br>轻点右上角的小房子，可以重新面向生日桌。</p><button id="resetProgress" class="action secondary">重新准备生日惊喜</button>`,'help-copy'),'help');$('#resetProgress').onclick=()=>{candleOut=false;night=false;discovered.clear();cupcakeBites=[0,0,0];syncCupcakes();persist();fire.visible=true;candleLight.intensity=3;setLighting();$('#discoveries').textContent='00 / '+total;closeModal();toast('蜡烛重新点好了，惊喜也准备好了。')}}
$('#help').onclick=help;$('#resetView').onclick=()=>{if(dialog.open)closeModal();returnView=null;controls.enabled=true;for(let k of ['x','y','z']){tween(controls.target,k,homeTarget[k]);tween(camera.position,k,homeEye[k])}tween(camera,'zoom',1);};
$('#accessible').onclick=()=>{const list=[['cake','生日餐桌 · 蛋糕'],['gramophone','边柜 · 留声机'],['letter','桌边 · 信封'],['flowers','圆凳 · 百合花'],['gift','地毯旁 · 礼物盒'],['plushGift','橘色礼物盒'],['floorbooks','左侧地上的书'],['cupcake0','桌上小蛋糕 1'],['cupcake1','桌上小蛋糕 2'],['cupcake2','桌上小蛋糕 3'],['sydney','书架 · 悉尼纪念品'],['camera','小圆桌 · 照相机'],['globe','书架 · 地球仪'],['fireplace','左侧小壁炉'],['window','窗户'],['curtain','窗帘'],['lamp','落地灯'],['drawer','边柜抽屉'],['clock','墙上的时钟'],['bear','灰色床上的小熊'],['record','边柜上的唱片'],['balloon0','一颗气球']];openModal(panel(`<p class="eyebrow">FIND YOUR OWN WAY</p><h1>房间里的小物件</h1><div class="object-list">${list.map(([id,s])=>`<button data-open="${id}">${s}<span>${discovered.has(id.startsWith('balloon')?'balloon':id)?'已发现':'↗'}</span></button>`).join('')}</div><p class="quiet">也可以收起这页，直接点击房间中的物品。</p>`),'explore');content.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{closeModal();setTimeout(()=>activate(b.dataset.open),250)})};
$('#enter').onclick=()=>{started=true;$('#intro').classList.add('gone');playMusic();burst(170);tween(renderer,'toneMappingExposure',1.18,2200);setLighting();chime();setTimeout(()=>{$('#hint').style.opacity='.65'},6000)};
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<650?78:70;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}addEventListener('resize',resize);resize();
fire.visible=!candleOut;candleLight.intensity=candleOut?0:3;setLighting();renderer.toneMappingExposure=.66;
let lastTime=0;function animate(t){requestAnimationFrame(animate);const s=t*.001;for(let i=tweens.length-1;i>=0;i--)if(!tweens[i](t))tweens.splice(i,1);camera.updateProjectionMatrix();if(musicOn)record.rotation.y-=.012;balloons.forEach(b=>{if(!tweens.length)b.g.position.y=b.base+Math.sin(s*.8+b.i)*.05;b.g.rotation.z=Math.sin(s*.7+b.i)*.025});animated.forEach(a=>a.g.rotation.z=Math.sin(s*.8+a.phase)*.025);flames.forEach(f=>{f.scale.y=.1*(1+Math.sin(s*12)*.08);f.rotation.z=Math.sin(s*9)*.1});hearthFlames.forEach((f,i)=>{f.scale.y=(.23+(i%2)*.07)*(1+Math.sin(s*6+i)*.1)});if(started&&candleOut)bulbs.forEach((b,i)=>b.material.emissiveIntensity=.7+(Math.sin(s*2+i*.5)+1)*.5);controls.update();if(tweens.length)renderer.invalidate?.();renderer.render(scene,camera);lastTime=t;}
